Rule.Source:
  import java.util.*;
  import sailpoint.tools.*;
  import sailpoint.object.Identity;
  import sailpoint.object.Application;
  import sailpoint.object.Custom;
  import sailpoint.object.Workflow;

  import org.apache.log4j.Logger;

 Logger log = Logger.getLogger("iiq.alpha.rule.Alpha-Rule-Joiner-Email Args Processor-Workflow Rule"); 
  log.debug("Alpha-Rule-Joiner-Email Args Processor-Workflow Rule STARTS");

  List emailArgsListFinal = new ArrayList(); //final List of Maps that should be returned
  Identity identity = context.getObject(Identity.class,identityName);

  //To send email on Joiner Success. Get the first Active Manager, form the Map with emailTemplate,to. Add the map to the final List.  
  String joinerEmailTemplate = (String) getValueFromCustomObject("Alpha-Custom-Joiner Custom Object","joinerSuccess_emailTemplate"); 
  String joineradAccountCreationEmailTemplate = (String) getValueFromCustomObject("Alpha-Custom-Joiner Custom Object","joinerSuccess_emailTemplate");
  log.debug("joinerEmailTemplate :"+joinerEmailTemplate);
  log.debug("joineradAccountCreationEmailTemplate :"+joineradAccountCreationEmailTemplate);

  Identity validManager = null;  

  Map joinerSuccessEmailMap = new HashMap(); 
  Map adAccCreationEmailMap = new HashMap(); 

  validManager = getValidManagerRecursive(context,identity,"spadmin");
  
  log.debug("joinerSuccessTo : "+ validManager.getEmail());

  joinerSuccessEmailMap.put("to",validManager.getEmail());
  joinerSuccessEmailMap.put("emailTemplate",joinerEmailTemplate);
  
  log.debug("adAccCreation : "+ validManager.getEmail());

  adAccCreationEmailMap.put("to",validManager.getEmail());
  adAccCreationEmailMap.put("emailTemplate",joineradAccountCreationEmailTemplate);  

  emailArgsListFinal.add(joinerSuccessEmailMap);
  emailArgsListFinal.add(adAccCreationEmailMap);


  log.debug("Final emailArgsList: "+emailArgsListFinal);
  return emailArgsListFinal;
